"use client";
import VendorShell from "../../../components/VendorShell";
import { useEffect,useMemo,useState } from "react";
import { api,patch,post } from "../../../lib/api";
type V={id:string;productId:string;name:string;priceOverride:number|null;displayOrder:number;product:{id:string;name:string;priceAmount:number;isAvailable:boolean};inventory:{quantity:number}|null};
type P={id:string;name:string;priceAmount:number}; const money=(n:number)=>`₦${(n/100).toLocaleString("en-NG",{maximumFractionDigits:2})}`;
export default function Variants(){const[v,setV]=useState<V[]>([]),[p,setP]=useState<P[]>([]),[q,setQ]=useState(""),[pf,setPf]=useState("all"),[loading,setLoading]=useState(true),[error,setError]=useState(""),[success,setSuccess]=useState(""),[modal,setModal]=useState(false),[edit,setEdit]=useState<V|null>(null),[pid,setPid]=useState(""),[name,setName]=useState(""),[price,setPrice]=useState(""),[stock,setStock]=useState(""),[saving,setSaving]=useState(false);
async function load(){try{setLoading(true);setError("");const[a,b]=await Promise.all([api<V[]>("/api/vendor/variants"),api<P[]>("/api/vendor/products")]);setV(Array.isArray(a)?a:[]);setP(Array.isArray(b)?b:[])}catch(e:any){setError(e?.message||"Failed to load variants.")}finally{setLoading(false)}}useEffect(()=>{load()},[]);
const rows=useMemo(()=>v.filter(x=>(!q||`${x.name} ${x.product.name}`.toLowerCase().includes(q.toLowerCase()))&&(pf==="all"||x.productId===pf)),[v,q,pf]);
function openCreate(){setEdit(null);setPid(p[0]?.id||"");setName("");setPrice("");setStock("");setModal(true)}function openEdit(x:V){setEdit(x);setPid(x.productId);setName(x.name);setPrice(x.priceOverride==null?"":String(x.priceOverride/100));setStock(String(x.inventory?.quantity??0));setModal(true)}
async function save(){try{setSaving(true);setError("");const n=Number(price),s=Number(stock||0);if(!pid)throw Error("Select a product.");if(!name.trim())throw Error("Variant name is required.");if(price!==""&&(!Number.isFinite(n)||n<0))throw Error("Enter a valid price override.");if(!Number.isInteger(s)||s<0)throw Error("Stock must be a whole number of 0 or more.");if(edit){await patch(`/api/vendor/variants/${edit.id}`,{name:name.trim(),priceOverride:price===""?null:Math.round(n*100)});const old=edit.inventory?.quantity??0;if(s!==old)await patch(`/api/vendor/products/${edit.productId}/stock`,{quantityDelta:s-old,variantId:edit.id});setSuccess("Variant updated successfully.")}else{await post(`/api/vendor/products/${pid}/variants`,{name:name.trim(),priceOverride:price===""?undefined:Math.round(n*100),initialStock:s});setSuccess("Variant created successfully")}setModal(false);await load()}catch(e:any){setError(e?.message||"Failed to save variant.")}finally{setSaving(false)}}
async function del(x:V){if(!confirm(`Delete “${x.name}” from ${x.product.name}?`))return;try{await post(`/api/vendor/variants/${x.id}/delete`);setSuccess("Variant deleted.");await load()}catch(e:any){setError(e?.message||"Failed to delete variant.")}}
async function move(x:V,d:number){const a=v.filter(y=>y.productId===x.productId).sort((m,n)=>m.displayOrder-n.displayOrder),i=a.findIndex(y=>y.id===x.id),j=i+d;if(j<0||j>=a.length)return;[a[i],a[j]]=[a[j],a[i]];try{await post(`/api/vendor/products/${x.productId}/variants/reorder`,{variantIds:a.map(y=>y.id)});await load()}catch(e:any){setError(e?.message||"Failed to reorder variants.")}}
return <VendorShell><main className="page-content"><div className="page-heading"><div><div className="eyebrow">CATALOG</div><h1>Variants</h1><p className="muted">Manage sellable versions such as size, flavor, model, color, or pack.</p></div><button className="btn primary" onClick={openCreate}>＋ Add variant</button></div>{error&&<div className="alert error">{error}</div>}{success&&<div className="alert success">{success}</div>}<div className="metric-grid"><div className="metric-card"><span>Total variants</span><strong>{v.length}</strong></div><div className="metric-card"><span>Products with variants</span><strong>{new Set(v.map(x=>x.productId)).size}</strong></div><div className="metric-card"><span>Low stock</span><strong>{v.filter(x=>(x.inventory?.quantity??0)<=10).length}</strong></div><div className="metric-card"><span>Out of stock</span><strong>{v.filter(x=>(x.inventory?.quantity??0)===0).length}</strong></div></div><section className="content-card"><div className="toolbar"><input className="input search-input" value={q} onChange={e=>setQ(e.target.value)} placeholder="Search variants or products..."/><select className="input filter-select" value={pf} onChange={e=>setPf(e.target.value)}><option value="all">All products</option>{p.filter(x=>v.some(y=>y.productId===x.id)).map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select><button className="btn secondary" onClick={load}>Refresh</button></div>{loading?<div className="state-panel"><h3>Loading variants…</h3></div>:!rows.length?<div className="state-panel"><div className="state-icon">◇</div><h3>{v.length?"No variants match your filters":"No variants yet"}</h3><p className="muted">Create a variant when a product has distinct sellable versions.</p>{!v.length&&<button className="btn primary" onClick={openCreate}>Create first variant</button>}</div>:<div className="table-wrap"><table className="data-table"><thead><tr><th>Variant</th><th>Product</th><th>Price</th><th>Stock</th><th>Order</th><th>Actions</th></tr></thead><tbody>{rows.map(x=>{const s=x.inventory?.quantity??0;return <tr key={x.id}><td><div className="table-primary">{x.name}</div><div className="table-secondary">{x.priceOverride!=null?`Override ${money(x.priceOverride)}`:"Uses product price"}</div></td><td>{x.product.name}</td><td><strong>{money(x.priceOverride??x.product.priceAmount)}</strong></td><td><span className={`status-badge ${s===0?"status-danger":s<=10?"status-warning":"status-active"}`}>{s} in stock</span></td><td><div className="reorder-actions"><button className="icon-button" onClick={()=>move(x,-1)}>↑</button><button className="icon-button" onClick={()=>move(x,1)}>↓</button></div></td><td><div className="row-actions"><button className="text-button" onClick={()=>openEdit(x)}>Edit</button><button className="text-button danger-text" onClick={()=>del(x)}>Delete</button></div></td></tr>})}</tbody></table></div>}</section><div className="info-banner"><strong>Variant rule</strong><span>Use variants for distinct sellable versions. Required/optional customization groups, min/max selections, and add-ons will be built in the next module.</span></div>{modal&&<div className="modal-backdrop" onMouseDown={e=>e.currentTarget===e.target&&setModal(false)}><section className="small-modal"><button className="drawer-close modal-x" onClick={()=>setModal(false)}>×</button><div className="eyebrow">{edit?"EDIT VARIANT":"NEW VARIANT"}</div><h2>{edit?"Edit variant":"Add variant"}</h2><p className="muted">Attach a sellable version to one product.</p><label>Product<select className="input" disabled={!!edit} value={pid} onChange={e=>setPid(e.target.value)}><option value="">Select product</option>{p.map(x=><option key={x.id} value={x.id}>{x.name}</option>)}</select></label><label>Variant name<input className="input" value={name} onChange={e=>setName(e.target.value)} placeholder="e.g. Large, 128GB, Black"/></label><label>Price override <span className="field-optional">Optional</span><input className="input" type="number" min="0" step="0.01" value={price} onChange={e=>setPrice(e.target.value)} placeholder="Blank = product price"/></label><label>{edit?"Current stock":"Initial stock"}<input className="input" type="number" min="0" step="1" value={stock} onChange={e=>setStock(e.target.value)} placeholder="0"/></label><div className="modal-actions"><button className="btn secondary" onClick={()=>setModal(false)}>Cancel</button><button className="btn primary" disabled={saving} onClick={save}>{saving?"Saving…":edit?"Save changes":"Create variant"}</button></div></section></div>}</main></VendorShell>}
